--- src/parse.js ---
export function parseCsv(text) {
  const lines = text.split("\n").filter((line) => line.length > 0);
  const [headerLine, ...dataLines] = lines;
  const header = headerLine.split(",");
  return dataLines.map((line) => {
    const cells = line.split(",");
    return Object.fromEntries(header.map((column, index) => [column, cells[index] ?? ""]));
  });
}
--- src/report.js ---
export function groupRows(rows, groupColumn, sumColumn) {
  const totals = new Map();
  for (const row of rows) {
    const key = row[groupColumn];
    totals.set(key, (totals.get(key) ?? 0) + Number(row[sumColumn]));
  }
  return [...totals].map(([key, total]) => ({ [groupColumn]: key, [`sum_${sumColumn}`]: total }));
}

export function formatTable(rows) {
  if (rows.length === 0) return "";
  const columns = Object.keys(rows[0]);
  const widths = columns.map((column) => Math.max(column.length, ...rows.map((row) => String(row[column]).length)));
  const formatLine = (cells) => cells.map((cell, index) => String(cell).padEnd(widths[index])).join("  ").trimEnd();
  return [formatLine(columns), ...rows.map((row) => formatLine(columns.map((column) => row[column])))].join("\n") + "\n";
}
--- src/cli.js ---
import { readFileSync } from "node:fs";
import { parseCsv } from "./parse.js";
import { formatTable, groupRows } from "./report.js";

const USAGE = "usage: csvreport <input.csv> [--group-by <column> --sum <column>]\n";
const EXIT_OK = 0;
const EXIT_USAGE = 1;

function parseArguments(argv) {
  const options = { input: undefined, groupBy: undefined, sum: undefined };
  for (let index = 0; index < argv.length; index += 1) {
    const argument = argv[index];
    if (argument === "--group-by") options.groupBy = argv[++index];
    else if (argument === "--sum") options.sum = argv[++index];
    else options.input = argument;
  }
  return options;
}

export function run(argv, io) {
  const options = parseArguments(argv);
  if (!options.input) {
    io.stderr(USAGE);
    return EXIT_USAGE;
  }
  const rows = parseCsv(readFileSync(options.input, "utf8"));
  const report = options.groupBy ? groupRows(rows, options.groupBy, options.sum) : rows;
  io.stdout(formatTable(report));
  return EXIT_OK;
}
